mapper.select:
select MHFLBS "mhflbs",SJFL "sjfl",FLMC "flmc",LMURL "lmurl",SFXS "sfxs",PX "px",BZ "bz",JB "jb" from MH_MHFL
where sjfl is null

    and flmc like CONCAT( '%',#{flmc},'%');

select LINKID,TITLE,URL,ORDERNO from MH_LINK where 1=1
and title like concat('%',#{title},'%');
order by ORDERNO,LINKID
